import{_ as l,C as n,o as a,c as d,a4 as s,E as i}from"./chunks/framework.BNWYI55R.js";const S=JSON.parse('{"title":"客户端配置指南：Clash Verge Rev、Sing-box 与多端配置","description":"主流代理客户端配置教程。提供 Windows、macOS、iOS、Android 跨平台客户端选择、内核特性对比与订阅导入指南。","frontmatter":{"title":"客户端配置指南：Clash Verge Rev、Sing-box 与多端配置","description":"主流代理客户端配置教程。提供 Windows、macOS、iOS、Android 跨平台客户端选择、内核特性对比与订阅导入指南。","h1":"客户端配置指南：Clash Verge Rev、Sing-box 与多端配置","pageType":"article","canonicalPath":"/clients/","primaryIntent":"客户端使用指南：掌握跨平台代理客户端的选择、订阅导入与分流配置","verifiedAt":"2026-10-21T00:00:00.000Z","modifiedAt":"2026-10-21T00:00:00.000Z"},"headers":[],"relativePath":"clients/index.md","filePath":"clients/index.md","lastUpdated":1792569090000}'),r={name:"clients/index.md"};function o(g,t,x,f,h,y){const e=n("RelatedLinks");return a(),d("div",null,[t[0]||(t[0]=s('<h1 id="客户端配置指南-clash-verge-rev、sing-box-与多端配置" tabindex="-1">客户端配置指南：Clash Verge Rev、Sing-box 与多端配置 <a class="header-anchor" href="#客户端配置指南-clash-verge-rev、sing-box-与多端配置" aria-label="Permalink to &quot;客户端配置指南：Clash Verge Rev、Sing-box 与多端配置&quot;">​</a></h1><p>拥有一个优质的机场订阅只是第一步，选择一个高效、稳定且契合自身操作习惯的客户端内核，才能将节点的网络性能发挥到极致。</p><p>本指南面向主流操作系统（Windows、macOS、iOS、Android），梳理当前最推荐的开源与高评价客户端，并提供清晰的配置避坑要点。</p><hr><h2 id="跨平台主流客户端矩阵" tabindex="-1">跨平台主流客户端矩阵 <a class="header-anchor" href="#跨平台主流客户端矩阵" aria-label="Permalink to &quot;跨平台主流客户端矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">操作系统</th><th style="text-align:left;">推荐客户端名称</th><th style="text-align:left;">底层核心</th><th style="text-align:left;">开源状态</th><th style="text-align:left;">授权模式</th><th style="text-align:left;">核心特点与适用人群</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows</strong></td><td style="text-align:left;"><strong>Clash Verge Rev</strong></td><td style="text-align:left;">Mihomo (原 Meta)</td><td style="text-align:left;">完全开源</td><td style="text-align:left;">免费开源</td><td style="text-align:left;">现代简白 UI、全面支持 VLESS/Reality/Hysteria 2、新手与老手通用</td></tr><tr><td style="text-align:left;"><strong>Windows</strong></td><td style="text-align:left;"><strong>Sing-box GUI</strong></td><td style="text-align:left;">Sing-box</td><td style="text-align:left;">完全开源</td><td style="text-align:left;">免费开源</td><td style="text-align:left;">极低系统资源占用、原生规则集引擎、适合追求极致性能的极客</td></tr><tr><td style="text-align:left;"><strong>macOS</strong></td><td style="text-align:left;"><strong>Clash Verge Rev</strong></td><td style="text-align:left;">Mihomo</td><td style="text-align:left;">完全开源</td><td style="text-align:left;">免费开源</td><td style="text-align:left;">完美适配 Apple Silicon 芯片、原生系统代理与 TUN 模式</td></tr><tr><td style="text-align:left;"><strong>macOS</strong></td><td style="text-align:left;"><strong>Surge for Mac</strong></td><td style="text-align:left;">专有核心</td><td style="text-align:left;">闭源</td><td style="text-align:left;">商业买断</td><td style="text-align:left;">网络调试神器、专业抓包与精准分流、适合专业开发者</td></tr><tr><td style="text-align:left;"><strong>iOS / iPadOS</strong></td><td style="text-align:left;"><strong>Shadowrocket (小火箭)</strong></td><td style="text-align:left;">专有核心</td><td style="text-align:left;">闭源</td><td style="text-align:left;">App Store 商业付费 ($2.99)</td><td style="text-align:left;">经典易用、协议支持极全、扫码即连、大众首选</td></tr><tr><td style="text-align:left;"><strong>iOS / iPadOS</strong></td><td style="text-align:left;"><strong>Loon / Quantumult X</strong></td><td style="text-align:left;">专有核心</td><td style="text-align:left;">闭源</td><td style="text-align:left;">App Store 商业付费</td><td style="text-align:left;">强大的脚本与重写功能、界面优雅、适合高级玩机党</td></tr><tr><td style="text-align:left;"><strong>Android</strong></td><td style="text-align:left;"><strong>Clash Meta for Android</strong></td><td style="text-align:left;">Mihomo</td><td style="text-align:left;">完全开源</td><td style="text-align:left;">免费开源</td><td style="text-align:left;">稳定成熟、支持丰富分流规则、安卓用户标配</td></tr><tr><td style="text-align:left;"><strong>Android</strong></td><td style="text-align:left;"><strong>Sing-box (Android)</strong></td><td style="text-align:left;">Sing-box</td><td style="text-align:left;">完全开源</td><td style="text-align:left;">免费开源</td><td style="text-align:left;">启动迅捷、省电节能、配置简洁</td></tr></tbody></table><hr><h2 id="核心配置避坑三大守则" tabindex="-1">核心配置避坑三大守则 <a class="header-anchor" href="#核心配置避坑三大守则" aria-label="Permalink to &quot;核心配置避坑三大守则&quot;">​</a></h2><h3 id="_1-优先开启-tun-虚拟网卡模式-tun-mode" tabindex="-1">1. 优先开启 TUN 虚拟网卡模式（TUN Mode） <a class="header-anchor" href="#_1-优先开启-tun-虚拟网卡模式-tun-mode" aria-label="Permalink to &quot;1. 优先开启 TUN 虚拟网卡模式（TUN Mode）&quot;">​</a></h3><p>传统的系统代理（System Proxy）仅能拦截支持 HTTP/HTTPS 代理协议的浏览器请求，无法接管命令行终端（CMD / PowerShell / Terminal）、桌面客户端（如 ChatGPT 官方桌面端、Spotify）或游戏进程的流量。</p><ul><li><strong>推荐操作</strong>：在 Clash Verge Rev 或 Sing-box 设置中安装虚拟网卡驱动（Wintun / TUN），并开启 <strong>TUN 模式</strong>。这将接管操作系统全量网络栈，从根本上解决“浏览器能上网但桌面 App 报错无法连接”的顽疾。</li></ul><h3 id="_2-避免激进的全局代理-坚持智能分流-rule-mode" tabindex="-1">2. 避免激进的全局代理，坚持智能分流（Rule Mode） <a class="header-anchor" href="#_2-避免激进的全局代理-坚持智能分流-rule-mode" aria-label="Permalink to &quot;2. 避免激进的全局代理，坚持智能分流（Rule Mode）&quot;">​</a></h3><ul><li><strong>规则模式（Rule）</strong>：客户端会自动根据目标域名与 IP 分流。访问国内网站（百度、淘宝、B站）直接直连，访问海外服务（Google、OpenAI、Netflix）自动走专线代理；</li><li><strong>错误示范</strong>：长期开启全局代理（Global Mode），不仅会导致国内访问变慢，还会极速消耗你宝贵的机场专线流量额度。</li></ul><h3 id="_3-dns-污染防范-fake-ip-模式" tabindex="-1">3. DNS 污染防范（Fake-IP 模式） <a class="header-anchor" href="#_3-dns-污染防范-fake-ip-模式" aria-label="Permalink to &quot;3. DNS 污染防范（Fake-IP 模式）&quot;">​</a></h3><ul><li>现代客户端内核普遍推荐启用 <strong>Fake-IP 模式</strong>。当浏览器发起 DNS 查询时，客户端立即返回一个虚拟的保留内网 IP，并将真实的域名解析工作交由海外机场节点的远程服务器完成。这不仅将 DNS 查询耗时压缩至 0ms，更能彻底杜绝国内本地 DNS 污染导致的连接失败。</li></ul>',15)),i(e,{links:[{title:"AI使用指南与网络排障 (/guides/)",desc:"查看 ChatGPT 403 阻断、长连接断流与账号风控完整解决方案",url:"/guides/"},{title:"机场综合推荐指南 (/recommend/)",desc:"多设备兼容性与各预算段主力备用方案评选",url:"/recommend/"},{title:"解锁实测实验中心 (/tests/)",desc:"查看客户端内核在标准测试中的网络抖动与抓包数据",url:"/tests/"}]})])}const u=l(r,[["render",o]]);export{S as __pageData,u as default};
